func UpdateInventory(ctx context.Context, sku string, qty int) error {
    if err := db.UpdateInventory(ctx, sku, qty); err != nil {
        return fmt.Errorf("update inventory %s: %w", sku, err)
    }

    key := "inv:" + sku
    data, err := json.Marshal(Inventory{SKU: sku, Qty: qty})
    if err != nil {
        return fmt.Errorf("encode inventory %s: %w", sku, err)
    }

    if serr := rdb.Set(ctx, key, data, jitteredTTL(time.Hour)).Err(); serr != nil {
        if derr := rdb.Del(ctx, key).Err(); derr != nil {
            cacheStaleUnbounded.Inc()
            slog.ErrorContext(ctx, "cache write and invalidate both failed; entry is stale until TTL",
                "key", key, "set_err", serr, "del_err", derr)
            return fmt.Errorf("%w: %s stale until TTL", ErrCacheInconsistent, key)
        }
        slog.WarnContext(ctx, "cache write failed, key invalidated", "key", key, "err", serr)
    }
    return nil
}
